import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

    @staticmethod
    def numpy_to_gsl_matrix(np_array):
        rows, cols = np_array.shape
        gsl_matrix = GSLMatrix(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl_matrix.matrix[i][j] = np_array[i][j]
        return gsl_matrix

    @staticmethod
    def gsl_matrix_to_numpy(gsl_matrix):
        np_array = np.zeros((gsl_matrix.rows, gsl_matrix.cols))
        for i in range(gsl_matrix.rows):
            for j in range(gsl_matrix.cols):
                np_array[i][j] = gsl_matrix.matrix[i][j]
        return np_array

