        self.cols = cols
        self._allocate()

    def _allocate(self):
        self.data = (ctypes.c_double * (self.rows * self.cols))()
        self.matrix = ctypes.pointer(ctypes.pointer(ctypes.Structure()))
        gsl.gsl_matrix_alloc.restype = ctypes.c_void_p
        self.matrix.contents = ctypes.cast(gsl.gsl_matrix_alloc(self.rows, self.cols), ctypes.POINTER(ctypes.Structure))

    def free(self):
        gsl.gsl_matrix_free(self.matrix)

    def to_numpy(self):
        return np.ctypeslib.as_array(self.data, shape=(self.rows, self.cols))

    @staticmethod
    def list_to_ctypes_matrix(lst):
        rows = len(lst)
        cols = len(lst[0])
        matrix = GSLMatrix(rows, cols)
        for i in range(rows):
            for j in range(cols):
