import numpy as np

class RingBuf:
    def __init__(self, size):
        self.size = size
        self.buffer = np.zeros(size, dtype=np.int32)
        self.start = 0
        self.end = 0

    def insert(self, value):
        if (self.end + 1) % self.size == self.start:
            return False  # Buffer is full
        self.buffer[self.end] = value
        self.end = (self.end + 1) % self.size
        return True

    def to_list(self):
        if self.end >= self.start:
            return self.buffer[self.start:self.end].tolist()
        else:
            return self.buffer[self.start:].tolist() + self.buffer[:self.end].tolist()

